import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import http from 'node:http';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

export const PKG_ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');

// Packs agentci into one self-contained .tgz (no dependencies), so it can travel to another
// machine over the network, a USB stick or scp – no git, no npm registry needed.
export function packBundle(outDir = process.cwd()) {
  fs.mkdirSync(outDir, { recursive: true });
  const r = spawnSync('npm', ['pack', '--pack-destination', outDir, '--silent'], {
    cwd: PKG_ROOT, encoding: 'utf8', timeout: 120_000,
  });
  if (r.status !== 0) throw new Error(`npm pack failed: ${(r.stderr || r.stdout || '').trim().slice(-400)}`);
  const name = r.stdout.trim().split('\n').filter(Boolean).pop();
  const file = path.join(outDir, path.basename(name));
  if (!fs.existsSync(file)) throw new Error(`npm pack produced no file (${file})`);
  const script = path.join(outDir, 'install-agentci.sh');
  fs.writeFileSync(script, installerScript(path.basename(file)), { mode: 0o755 });
  return { file, script, bytes: fs.statSync(file).size };
}

// The script that runs ON THE OTHER MACHINE. With a URL it downloads the bundle first,
// otherwise it expects the .tgz next to itself (USB stick, scp).
export function installerScript(tgzName, url = '') {
  return `#!/usr/bin/env sh
# Install agentci – generated by "agentci bundle".
set -e
TGZ="${tgzName}"
URL="${url}"
DIR="$(cd "$(dirname "$0")" 2>/dev/null && pwd || echo .)"

command -v node >/dev/null || { echo "Node.js missing – please install Node 20 or newer"; exit 1; }
MAJOR=$(node -p 'process.versions.node.split(".")[0]')
[ "$MAJOR" -ge 20 ] || { echo "Node $(node -v) is too old – agentci needs Node 20+ (Fedora: sudo dnf install nodejs; Oracle/RHEL: sudo dnf module enable -y nodejs:22 && sudo dnf install -y nodejs)"; exit 1; }
command -v npm >/dev/null || { echo "npm missing"; exit 1; }

if [ -n "$URL" ] && [ ! -f "$DIR/$TGZ" ]; then
  echo "Downloading agentci from $URL …"
  if command -v curl >/dev/null; then curl -fsSL "$URL/$TGZ" -o "$DIR/$TGZ";
  elif command -v wget >/dev/null; then wget -q "$URL/$TGZ" -O "$DIR/$TGZ";
  else echo "curl or wget required"; exit 1; fi
fi
[ -f "$DIR/$TGZ" ] || { echo "package $TGZ not found"; exit 1; }

echo "Installing agentci …"
npm install -g "$DIR/$TGZ" >/dev/null 2>&1 || sudo npm install -g "$DIR/$TGZ" >/dev/null

BIN="$(command -v agentci || true)"
if [ -z "$BIN" ]; then
  PREFIX="$(npm prefix -g 2>/dev/null || echo /usr/local)"
  BIN="$PREFIX/bin/agentci"
  echo ""
  echo "Note: $PREFIX/bin is not in your PATH. Add it, e.g.:"
  echo "  echo 'export PATH=\$PATH:$PREFIX/bin' >> ~/.bashrc && . ~/.bashrc"
fi
echo ""
echo "Done: $BIN"
echo ""
echo "Next steps:"
echo "  agentci doctor                 check install and logins"
echo "  agentci gateway                start the gateway (machine WITH internet)"
echo "  agentci ui                     web interface (your work machine)"
echo ""
echo "Missing Claude/Codex? npm i -g @anthropic-ai/claude-code @openai/codex"
`;
}

// Serves the bundle plus a one-line installer for the other machine.
export function serveBundle({ outDir, port = 4319, host = '0.0.0.0' } = {}) {
  const { file, bytes } = packBundle(outDir || fs.mkdtempSync(path.join(os.tmpdir(), 'agentci-bundle-')));
  const tgz = path.basename(file);
  const server = http.createServer((req, res) => {
    const url = new URL(req.url, 'http://x');
    if (url.pathname === `/${tgz}` || url.pathname === '/agentci.tgz') {
      res.writeHead(200, { 'Content-Type': 'application/gzip', 'Content-Length': bytes });
      fs.createReadStream(file).pipe(res);
      return;
    }
    if (url.pathname === '/' || url.pathname === '/install.sh') {
      const base = `http://${req.headers.host}`;
      res.writeHead(200, { 'Content-Type': 'text/x-shellscript; charset=utf-8' });
      res.end(installerScript(tgz, base));
      return;
    }
    res.writeHead(404, { 'Content-Type': 'text/plain' });
    res.end('not found');
  });
  return {
    file, tgz, bytes, server,
    listen: () => new Promise((resolve, reject) => {
      server.once('error', reject);
      server.listen(port, host, () => resolve(server.address().port));
    }),
    close: () => new Promise((r) => { server.closeAllConnections?.(); server.close(r); }),
  };
}

export function humanSize(n) {
  const u = ['B', 'kB', 'MB'];
  const i = Math.min(u.length - 1, Math.floor(Math.log(n || 1) / Math.log(1024)));
  return `${(n / 1024 ** i).toFixed(i ? 1 : 0)} ${u[i]}`;
}
